/**
 * Regenerates web/tests/fixtures/passkey.json — a real registration and assertion, produced by
 * the software authenticator, so the verify tests and the CPU benchmark read the same bytes a
 * browser would send instead of inventing them.
 *
 *   node --import tsx web/tests/fixtures/generate-passkey-fixture.mjs
 *
 * The credential's private key is discarded. Only the public half is checked in; that is all the
 * Worker ever stores.
 */
import { writeFileSync } from "node:fs"
import { b64url, createAssertion, createCredential } from "../helpers/webauthn.ts"

const RP_ID = "snip.test"
const ORIGIN = "https://snip.test"
const challenge = () => b64url(crypto.getRandomValues(new Uint8Array(32)))

const registrationChallenge = challenge()
const { response: registrationResponse, credential } = await createCredential({ rpID: RP_ID, origin: ORIGIN, challenge: registrationChallenge })

const authenticationChallenge = challenge()
const { response: authenticationResponse, counter } = await createAssertion({
  rpID: RP_ID,
  origin: ORIGIN,
  challenge: authenticationChallenge,
  credential,
})

const fixture = {
  $comment: "Generated by generate-passkey-fixture.mjs. A real P-256 registration and assertion for snip.test.",
  rpID: RP_ID,
  origin: ORIGIN,
  credential: { id: credential.id, publicKey: b64url(credential.publicKey), counter: 0 },
  registration: { challenge: registrationChallenge, response: registrationResponse },
  authentication: { challenge: authenticationChallenge, response: authenticationResponse, counter },
}

const out = new URL("./passkey.json", import.meta.url)
writeFileSync(out, `${JSON.stringify(fixture, null, 2)}\n`)
console.log(`wrote ${out.pathname}`)
